DIMENSION: port-stoi — definitive spec (all statements backed by observed runs on /workspace/dataset/test15_executable)

=================================================================
STEP 0 — argc gate. THIS RUNS BEFORE ANY PORT PARSING. (was missing/wrong in prior spec)
=================================================================
    // argv[0] is the program name.
    if argv.len() < 7 {              // fewer than 6 positional args
        // stdout: 0 bytes.  stderr: 0 bytes.  argv[3] is NEVER read.
        process::exit(1);
    }
    // Args beyond the 6th are ignored completely.
Evidence: ("http","e.com","abc","/","") [5 args] -> exit 1, 0B stdout, 0B stderr, no abort.
          ("http","e.com","99999999999999999999","/","") -> exit 1, silent.
          ("http","e.com","abc","/","","") [6] -> exit 134.  (...,"EXTRA") [7] -> exit 134.
          ("http","e.com","8080","/","","","9999") -> port 8080 (7th arg ignored).

=================================================================
STEP 1 — parse argv[3] with exact C++ std::stoi(s, nullptr, 10) semantics.
=================================================================
enum StoiErr { Invalid, OutOfRange }

fn cpp_stoi_base10(s: &[u8]) -> Result<i32, StoiErr> {
    let mut i = 0;

    // 1a. Skip a run of leading whitespace. The set is EXACTLY these six bytes
    //     and nothing else. Locale-independent (verified over 6 locales).
    //     0x09 HT, 0x0A LF, 0x0B VT, 0x0C FF, 0x0D CR, 0x20 SP
    while i < s.len() && matches!(s[i], 0x09|0x0A|0x0B|0x0C|0x0D|0x20) { i += 1; }
    //     NOT whitespace: 0x1C-0x1F, 0x7F, 0xA0, 0xC2 0xA0 (UTF-8 NBSP),
    //     U+2009, and every other byte in 1..=255.

    // 1b. At most ONE sign, immediately after the whitespace run.
    let mut neg = false;
    if i < s.len() && (s[i] == b'+' || s[i] == b'-') { neg = (s[i] == b'-'); i += 1; }
    //     A second sign, or whitespace after the sign, is NOT allowed (-> Invalid).

    // 1c. One or more ASCII '0'..'9'. Required IMMEDIATELY (no whitespace here).
    let start = i;
    let mut mag: i64 = 0;                 // must not wrap: use i64/i128/bignum + saturation
    while i < s.len() && s[i].is_ascii_digit() {
        mag = saturating_mul_add(mag, 10, (s[i] - b'0') as i64);   // saturate at > 2^63 is fine
        i += 1;
    }
    if i == start { return Err(Invalid); }        // no digits at all

    // 1d. EVERYTHING from index i onward is silently discarded — any bytes, any length,
    //     including more whitespace, letters, punctuation, non-ASCII, 100000 chars.

    let v: i64 = if neg { -mag } else { mag };
    if v < -2147483648 || v > 2147483647 { return Err(OutOfRange); }   // VALUE, not length
    Ok(v as i32)
}

Base is hard-coded 10 (NOT auto-base): "010"->10, "017"->17, "08"->8, "09"->9,
"0x10"->0, "0X10"->0, "0b11"->0, "0o17"->0, "0x7fffffff"->0.

Accepted examples: " 80"|"80 "|" 80 "|$'\t80'|$'\v80'|$'\f80'|$'\r80'|$'\n80'|
$' \t\n\v\f\r80'->80; "+80"->80; "080"->80; 5000 zeros+"80"->80; 100000 zeros+"443"->443;
"8 0"->8; "80abc"->80; "80.9"->80; "1e3"->1; "1_000"->1; "80-"->80; "80+"->80; "+80+"->80;
"8"+U+FF10->8; "80"+100000 'x'->80; 5000 zeros->0; "-"+5000 zeros+"0"->0.
Invalid examples: ""|"abc"|"abc80"|"e80"|"x80"|"/80"|":80"|"#80"|"%80"|".80"|"-.5"|
"-"|"+"|"--80"|"++80"|"+-80"|"-+80"|"+ 80"|"- 80"|"  +"|$'-\n80'|$'\n'|$'\t \r\n'|
5000 spaces|"\\n80" (literal backslash-n)|NBSP+"80"|U+2009+"80"|"８０"|"٨٠".

=================================================================
STEP 2 — error paths: uncaught exception => process death, NOTHING on stdout.
=================================================================
match cpp_stoi_base10(argv[3]) {
  Err(Invalid) => {
      // stdout: EXACTLY 0 bytes (true under stdbuf -o0, to a file, and through a pipe)
      write_all(stderr, b"terminate called after throwing an instance of 'std::invalid_argument'\n  what():  stoi\n");  // 87 bytes
      raise(SIGABRT);   // shell reports "Aborted (core dumped)", exit status 134;
                        // a waitpid consumer sees WIFSIGNALED with SIGABRT
  }
  Err(OutOfRange) => {
      // stdout: EXACTLY 0 bytes
      write_all(stderr, b"terminate called after throwing an instance of 'std::out_of_range'\n  what():  stoi\n");      // 83 bytes
      raise(SIGABRT);
  }
  Ok(n) => { /* STEP 3 */ }
}
NOTE the exact spacing: "…'\n" then TWO spaces, "what():", then TWO spaces, "stoi\n".
Overflow examples: "2147483648", "+2147483648", "-2147483649", "-0000002147483649",
"2147483648abc", "21474836470", 4000 '8's, 5000 zeros+"2147483648".
In-range endpoints do NOT throw: "2147483647", "+2147483647", "-2147483648",
"-0000002147483648", "  -2147483648  " -> all exit 0 (and normalize to -1 below).

=================================================================
STEP 3 — normalize ONCE at construction; store the normalized value.
=================================================================
    let port: i32 = if n >= 0 && n <= 65535 { n } else { -1 };
    // NOT clamped: 65536->-1 (not 65535), -5->-1, 2147483647->-1, -2147483648->-1.
    // Signed zero is in range: -0/+0/"-000" -> 0.
    // Both port() and to_string() read this normalized field. (Normalizing in the
    // getter instead is observationally identical for every possible input.)
